      return allUsers;
    } catch (e) {
      throw 'Đã xảy ra lỗi khi lấy danh sách người dùng: $e';
    }
  }

  Future<void> followUser(String currentUserId, String otherUserId) async {
    try {
      await _db.collection("Followers").add({
        'uid': currentUserId,
        'ortherid': otherUserId,
        'timestamp': FieldValue.serverTimestamp(),
      });
    } catch (e) {
      throw 'Lỗi khi theo dõi người dùng: $e';
    }
  }

  Future<void> unfollowUser(String currentUserId, String otherUserId) async {
    try {
      final snapshot = await _db
          .collection("Followers")
          .where('uid', isEqualTo: currentUserId)
          .where('ortherid', isEqualTo: otherUserId)
          .get();

      for (var doc in snapshot.docs) {
        await doc.reference.delete();
      }
    } catch (e) {
      throw 'Lỗi khi hủy theo dõi: $e';
    }
  }

  Future<List<String>> getFollowingIds(String uid) async {
    try {
      final snapshot = await _db.collection("Followers").where('uid', isEqualTo: uid).get();
      return snapshot.docs.map((doc) => doc.data()['ortherid'] as String).toList();
    } catch (e) {
      throw 'Lỗi khi lấy danh sách đang theo dõi: $e';
    }
  }

   Stream<List<String>> getFollowingStream(String uid) {
     return _db
         .collection("Followers")
         .where('uid', isEqualTo: uid)
         .snapshots()
         .map((snapshot) => snapshot.docs.map((doc) => (doc.data()['ortherid'] ?? "") as String).toList())
         .handleError((error) {
           debugPrint('❌ Error in following stream: $error');
           return <String>[];
         });
   }

  Future<List<String>> getFollowerIds(String uid) async {
    try {
      final snapshot = await _db.collection("Followers").where('ortherid', isEqualTo: uid).get();
      return snapshot.docs.map((doc) => doc.data()['uid'] as String).toList();
    } catch (e) {
      throw 'Lỗi khi lấy danh sách người theo dõi: $e';
    }
  }

   Stream<List<String>> getFollowerStream(String uid) {
     return _db
         .collection("Followers")
         .where('ortherid', isEqualTo: uid)
         .snapshots()
         .map((snapshot) => snapshot.docs.map((doc) => (doc.data()['uid'] ?? "") as String).toList())
         .handleError((error) {
           debugPrint('❌ Error in follower stream: $error');
           return <String>[];
         });
   }

  Future<bool> isFollowing(String currentUserId, String otherUserId) async {
    try {
      final snapshot = await _db
          .collection("Followers")
          .where('uid', isEqualTo: currentUserId)
          .where('ortherid', isEqualTo: otherUserId)
          .get();
      return snapshot.docs.isNotEmpty;
    } catch (e) {
      return false;
    }
  }
}

import 'package:runvix/Pages/Home/Widgets/Profile/add_manual_activity_screen.dart';
import 'package:runvix/export.dart';

class ProfileScreen extends StatefulWidget {
  const ProfileScreen({super.key});

  @override
  State<ProfileScreen> createState() => _ProfileScreenState();
}

class _ProfileScreenState extends State<ProfileScreen> with SingleTickerProviderStateMixin {
  late TabController _tabController;
  final userController = UserController.instance;
  final navigationController = NavigationController.instance;

  @override
  void initState() {
    super.initState();
    _initTabController();
  }

  void _initTabController() {
    _tabController = TabController(
      length: 2,
      vsync: this,
      initialIndex: navigationController.profileTabIndex.value,
    );

    // Lắng nghe thay đổi từ controller (khi chuyển từ trang chủ)
    ever(navigationController.profileTabIndex, (index) {
      if (_tabController.index != index) {
        _tabController.animateTo(index);
      }
    });

    // Cập nhật ngược lại controller khi người dùng vuốt tab
    _tabController.addListener(() {
      if (!_tabController.indexIsChanging) {
        navigationController.profileTabIndex.value = _tabController.index;
      }
    });
  }

  @override
  void dispose() {
    _tabController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.white,
      appBar: _buildAppBar(),
      body: TabBarView(
        controller: _tabController,
        children: const [
          ProfileProgressTab(),
          ProfileActivitiesTab(),
        ],
      ),
    );
  }

  /// Xây dựng AppBar sạch sẽ
  PreferredSizeWidget _buildAppBar() {
    return AppBar(
      backgroundColor: Colors.white,
      elevation: 0.5,
      leading: _buildProfileAvatar(),
      title: const Text(
        'Bạn',
        style: TextStyle(color: Colors.black, fontWeight: FontWeight.bold, fontSize: 18),
      ),
      centerTitle: true,
      actions: [
        _buildAddMenu(),
        IconButton(
          icon: const Icon(Icons.settings_outlined, color: Colors.black, size: 28),
          onPressed: () => Get.to(() =>  SettingsScreen()),
        ),
      ],
      bottom: _buildTabBar(),
    );
  }

  /// Widget ảnh đại diện trên AppBar
  Widget _buildProfileAvatar() {
    return Padding(
      padding: const EdgeInsets.all(10.0),
      child: GestureDetector(
        onTap: () => Get.to(() => const ProfileDetailScreen()),
        child: Obx(() {
          final networkImage = userController.user.value.profilePicture;
          return CircleAvatar(
            backgroundImage: NetworkImage(
              networkImage.isNotEmpty ? networkImage : 'https://picsum.photos/200',
            ),
          );
        }),
      ),
    );
  }

  /// Menu thêm mới (Popup ngay dưới nút Add)
  Widget _buildAddMenu() {
    return PopupMenuButton<int>(
      icon: const Icon(Icons.add_circle_outline, color: Colors.black, size: 28),
      offset: const Offset(0, 50), 
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
      color: Colors.white,
      elevation: 4,
      onSelected: (value) {
        if (value == 0) {
          Get.to(() => const CreatePostScreen());
        } else if (value == 2) {
          Get.to(() => const AddManualActivityScreen());
        }

      },
      itemBuilder: (context) => [
        _buildPopupMenuItem(0, 'Đăng', Icons.article_outlined),
        const PopupMenuDivider(height: 1),
        _buildPopupMenuItem(2, 'Hoạt động thủ công', Icons.insights_outlined),
      ],
    );
  }

  /// Helper tạo item cho PopupMenu với Icon bên phải
  PopupMenuItem<int> _buildPopupMenuItem(int value, String text, IconData icon) {
    return PopupMenuItem<int>(
      value: value,
      height: 40,
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Text(
            text,
            style: const TextStyle(color: Colors.black, fontSize: 15),
          ),
          const SizedBox(width: 12),
          Icon(icon, color: Colors.black54, size: 22),
        ],
      ),
    );
  }

  /// Xây dựng TabBar
  PreferredSizeWidget _buildTabBar() {
    return TabBar(
      controller: _tabController,
      labelColor: Colors.black,
      unselectedLabelColor: Colors.grey,
      indicatorColor: AppColors.buttonColor,
      indicatorWeight: 2,
      labelStyle: const TextStyle(fontWeight: FontWeight.bold, fontSize: 15),
      tabs: [
        const Tab(text: 'Tiến trình'),
        const Tab(text: 'Hoạt động'),
      ],
    );
  }
}

